ACMsg.MPY_FRAMEBUF_FRAMEBUFFER_HLINE = "Eine horizontale Linie beginnend bei (<b>x</b>, <b>y</b>) mit Breite <b>w</b> in Farbe <b>c</b> zeichnen.";
ACMsg.MPY_FRAMEBUF_FRAMEBUFFER_VLINE = "Eine vertikale Linie beginnend bei (<b>x</b>, <b>y</b>) mit Höhe <b>h</b> in Farbe <b>c</b> zeichnen.";
ACMsg.MPY_FRAMEBUF_FRAMEBUFFER_LINE = "Eine 1-Pixel-dicke Linie von (<b>x1</b>, <b>y1</b>) nach (<b>x2</b>, <b>y2</b>) in Farbe <b>c</b> zeichnen.";
ACMsg.MPY_FRAMEBUF_FRAMEBUFFER_RECT = "Ein Rechteck bei (<b>x</b>, <b>y</b>) mit Größe <b>w</b>×<b>h</b> in Farbe <b>c</b> zeichnen. Wenn <b>f</b> True ist, das Rechteck füllen; sonst nur die 1-Pixel-Umrandung zeichnen.";
ACMsg.MPY_FRAMEBUF_FRAMEBUFFER_ELLIPSE = "Eine Ellipse zentriert bei (<b>x</b>, <b>y</b>) mit Radien <b>xr</b>, <b>yr</b> in Farbe <b>c</b> zeichnen. Wenn <b>f</b> True ist, füllen. Optional beschränkt <b>m</b> das Zeichnen auf Quadranten über seine unteren 4 Bits.";
ACMsg.MPY_FRAMEBUF_FRAMEBUFFER_POLY = "Ein geschlossenes Polygon mit Versatz (<b>x</b>, <b>y</b>) aus Koordinatenpaaren in <b>coords</b> (ein <b>array</b> von Ganzzahlen wie <b>array('h', [x0, y0, x1, y1, ...])</b>) in Farbe <b>c</b> zeichnen. Wenn <b>f</b> True ist, füllen; sonst nur die Umrandung zeichnen.";
ACMsg.MPY_FRAMEBUF_FRAMEBUFFER_TEXT = "Zeichnet einen 8×8-Bitmap-Text <b>s</b> mit seiner oberen linken Ecke bei (<b>x</b>, <b>y</b>). Optional legt <b>c</b> die Farbe fest (Standard: 1).";
ACMsg.MPY_FRAMEBUF_FRAMEBUFFER_SCROLL = "Verschiebt den Inhalt des Framebuffers um (<b>xstep</b>, <b>ystep</b>). Pixel werden nicht umgebrochen; in freigelegten Bereichen können alte Farben sichtbar bleiben.";
ACMsg.MPY_FRAMEBUF_FRAMEBUFFER_BLIT = "Kopiert einen anderen Framebuffer <b>fbuf</b> auf diesen bei (<b>x</b>, <b>y</b>). Wenn <b>key</b> angegeben ist, wird diese Farbe als transparent behandelt. Optional ermöglicht <b>palette</b> das Übertragen zwischen verschiedenen Formaten.";
